import type { AuthProvider } from "ra-core";
import { canAccess } from "../commons/canAccess";

const apiOrigin = (import.meta.env.VITE_CLOUDFLARE_API_URL ?? "").replace(
  /\/$/,
  "",
);

const authRequest = async <T>(path: string, init?: RequestInit) => {
  const headers = new Headers(init?.headers);
  headers.set("Content-Type", "application/json");
  const response = await fetch(`${apiOrigin}/api/auth${path}`, {
    ...init,
    credentials: "include",
    headers,
  });
  const body = (await response.json().catch(() => ({}))) as T & {
    error?: { message?: string };
  };
  if (!response.ok)
    throw new Error(body.error?.message ?? "Authentication failed");
  return body;
};

type SessionResponse = {
  user: { id: string; name: string; email: string; image?: string | null };
};

export const authProvider: AuthProvider = {
  async login({ email, password, ssoDomain, redirectTo }) {
    if (ssoDomain) {
      const result = await authRequest<{ url?: string }>("/sign-in/sso", {
        method: "POST",
        body: JSON.stringify({
          domain: ssoDomain,
          callbackURL: redirectTo ?? window.location.origin,
          errorCallbackURL: window.location.href,
        }),
      });
      if (!result.url) throw new Error("SSO provider is not configured");
      window.location.assign(result.url);
      return;
    }
    await authRequest("/sign-in/email", {
      method: "POST",
      body: JSON.stringify({ email, password }),
    });
  },
  async logout() {
    await authRequest("/sign-out", { method: "POST", body: "{}" });
  },
  async checkAuth() {
    await authRequest<SessionResponse>("/get-session");
  },
  async checkError(error) {
    if (error?.status === 401 || error?.status === 403) throw error;
  },
  async getIdentity() {
    const response = await fetch(`${apiOrigin}/api/me`, {
      credentials: "include",
    });
    const body = (await response.json()) as {
      data?: {
        id: number;
        first_name: string;
        last_name: string;
        email: string;
        avatar?: string | null;
        administrator: boolean;
      };
    };
    if (!response.ok || !body.data) throw new Error("CRM identity unavailable");
    return {
      id: body.data.id,
      fullName: `${body.data.first_name} ${body.data.last_name}`,
      avatar: body.data.avatar ?? undefined,
      administrator: body.data.administrator,
    };
  },
  async canAccess(params) {
    const identity = await this.getIdentity!();
    return canAccess(identity.administrator ? "admin" : "user", params);
  },
  async resetPassword({ email }: { email: string }) {
    await authRequest("/request-password-reset", {
      method: "POST",
      body: JSON.stringify({
        email,
        redirectTo: `${window.location.origin}/reset-password`,
      }),
    });
  },
  async setPassword({ token, password }: { token: string; password: string }) {
    await authRequest("/reset-password", {
      method: "POST",
      body: JSON.stringify({ token, newPassword: password }),
    });
  },
};

export const getCurrentDate = () => {
  const now = new Date();
  const offset = now.getTimezoneOffset();
  const localDate = new Date(now.getTime() - offset * 60 * 1000);
  return localDate.toISOString().slice(0, 16);
};

export const formatNoteDate = (dateString: string) => {
  const date = new Date(dateString);
  date.setSeconds(0);
  date.setMilliseconds(0);
  return date.toISOString();
};

import { useListContext } from "ra-core";
import { useEffect, useMemo, useState } from "react";

/**
 * Turn a standard list context into an infinite pagination context by keeping track of all loaded pages and their data.
 * This allows to use the InfinitePagination component inside a standard List component.
 */
export const useAddInfinitePagination = () => {
  const { data, error, isPending, page, setPage, total, refetch } =
    useListContext();

  const [allPages, setAllPages] = useState<Record<number, any[]>>({});

  useEffect(() => {
    if (!data) {
      return;
    }
    setAllPages((prev) => ({ ...prev, [page]: data }));
  }, [page, setAllPages, data]);

  const allLoadedData = useMemo(() => {
    // Sort pages by page number and flatten the data
    return Object.entries(allPages)
      .sort(([pageA], [pageB]) => Number(pageA) - Number(pageB))
      .flatMap(([, pageData]) => pageData);
  }, [allPages]);

  return {
    isPending,
    error,
    data: allLoadedData,
    refetch,
    infinitePaginationContextValue: {
      fetchNextPage: async (): Promise<any> => {
        setPage(page + 1);
      },
      hasNextPage: allLoadedData.length < (total ?? 0),
      isFetchingNextPage: isPending,
      fetchPreviousPage: async (): Promise<any> => {
        setPage(page - 1);
      },
      hasPreviousPage: page > 1,
      isFetchingPreviousPage: false,
    },
  };
};

