type AuditEvent = {
  actionType: string;
  toolName: string | null;
  contactName: string | null;
  companyName: string | null;
  summary: string;
};

type AuditSink = (event: AuditEvent) => Promise<void>;

let auditSink: AuditSink = async () => {};

export function configureCopilotAudit(sink: AuditSink) {
  auditSink = sink;
}

const recentlyLogged = new Set<string>();

function makeKey(toolName: string, args: Record<string, unknown>): string {
  return `${toolName}:${JSON.stringify(args)}`;
}

function extractNames(args: Record<string, unknown>): {
  contactName: string | null;
  companyName: string | null;
} {
  return {
    contactName:
      (args.contactName as string) || (args.contact_name as string) || null,
    companyName:
      (args.companyName as string) ||
      (args.company as string) ||
      (args.company_name as string) ||
      null,
  };
}

const textArgument = (value: unknown, fallback = "") =>
  typeof value === "string" || typeof value === "number"
    ? String(value)
    : fallback;

const summaryRules: Record<string, (args: Record<string, unknown>) => string> =
  {
    getContactsByCompany: (a) =>
      `Fetched contacts for ${textArgument(a.companyName || "unknown")}`,
    getTopLeads: (a) => `Fetched top ${textArgument(a.limit || 10)} leads`,
    searchContacts: (a) =>
      `Searched contacts${a.company ? ` for ${textArgument(a.company)}` : ""}`,
    createTask: (a) =>
      `Created task: ${textArgument(a.description || "untitled")}`,
    draftEmail: (a) =>
      `Drafted email to ${textArgument(a.contactName || "unknown")}: ${textArgument(a.subject || "")}`,
    updateContactStatus: (a) =>
      `Updated contact status to ${textArgument(a.status || "unknown")}`,
    listDeals: (a) =>
      `Listed deals${a.companyName ? ` for ${textArgument(a.companyName)}` : ""}`,
    updateDeal: (a) => `Updated deal ${textArgument(a.dealId ?? "")}`,
    createNote: (a) =>
      `Created a note for contact ${textArgument(a.contactId ?? "")}`,
    analyzeContract: (a) =>
      `Loaded contract for ${textArgument(a.companyName || a.contactId || "unknown")}`,
  };

function generateSummary(
  toolName: string,
  args: Record<string, unknown>,
): string {
  if (typeof args.summary === "string" && args.summary.length > 0) {
    return args.summary;
  }
  const rule = summaryRules[toolName];
  if (rule) return rule(args);
  return `Called ${toolName}`;
}

async function postAuditEvent(event: AuditEvent): Promise<void> {
  try {
    await auditSink(event);
  } catch {
    // Audit logging should never break the app.
  }
}

export async function logToolCall(
  toolName: string,
  args: Record<string, unknown>,
): Promise<void> {
  const key = makeKey(toolName, args);
  recentlyLogged.add(key);
  setTimeout(() => recentlyLogged.delete(key), 10_000);

  const { contactName, companyName } = extractNames(args);
  await postAuditEvent({
    actionType: "tool_call",
    toolName,
    contactName,
    companyName,
    summary: generateSummary(toolName, args),
  });
}

export async function logComponentRender(
  toolName: string,
  args: Record<string, unknown>,
): Promise<void> {
  const key = makeKey(toolName, args);
  if (recentlyLogged.has(key)) return;

  const { contactName, companyName } = extractNames(args);
  await postAuditEvent({
    actionType: "component_render",
    toolName,
    contactName,
    companyName,
    summary: `Rendered ${toolName}`,
  });
}

export async function logAgentSummary(summary: string): Promise<void> {
  await postAuditEvent({
    actionType: "agent_summary",
    toolName: null,
    contactName: null,
    companyName: null,
    summary,
  });
}

import { useEffect, useRef } from "react";
import { useDataProvider, useGetIdentity } from "ra-core";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { logToolCall } from "./auditLogger";
import type { CrmDataProvider } from "../../providers/types";

export interface ForecastCardProps {
  args: Partial<{
    contactId: number;
    contactName: string;
    currentCategory: string;
    proposedCategory: string;
    currentProbability: number;
    proposedProbability: number;
    reason: string;
  }>;
  respond: ((response: unknown) => void) | undefined;
  status: string;
}

export function ForecastCard({
  args,
  respond,
  status: _status,
}: ForecastCardProps) {
  const { data: identity } = useGetIdentity({ staleTime: 0 });
  const dataProvider = useDataProvider<CrmDataProvider>();
  const isAdmin = !!(identity as { administrator?: boolean })?.administrator;

  const hasAutoResponded = useRef(false);

  // Non-admin: auto-respond after 2s delay so the user can read the proposal
  useEffect(() => {
    if (isAdmin || !respond || hasAutoResponded.current) return;

    const timer = setTimeout(() => {
      hasAutoResponded.current = true;
      respond({ approved: false, reason: "insufficient_role" });
      void logToolCall("updateRenewalForecast", {
        contactName: args.contactName,
        summary: `Forecast proposal shown to non-admin user (approval requires admin role)`,
      });
    }, 2000);

    return () => clearTimeout(timer);
  }, [isAdmin, respond, args.contactName]);

  const isExecuting = !!respond;

  return (
    <Card className="my-2" data-demo="hitl-card">
      <CardContent className="pt-4">
        <div className="mb-3">
          <p className="font-semibold text-sm mb-1">
            Renewal Forecast Update — {args.contactName}
          </p>
          <p className="text-xs text-muted-foreground mb-2">{args.reason}</p>
          <div className="grid grid-cols-2 gap-2 text-xs">
            <div className="bg-muted rounded p-2">
              <p className="font-medium text-muted-foreground">Current</p>
              <p>{args.currentCategory}</p>
              <p>{args.currentProbability}%</p>
            </div>
            <div className="bg-muted rounded p-2">
              <p className="font-medium text-muted-foreground">Proposed</p>
              <p>{args.proposedCategory}</p>
              <p>{args.proposedProbability}%</p>
            </div>
          </div>
        </div>
        {isAdmin && isExecuting && respond && (
          <div className="flex gap-2">
            <Button
              size="sm"
              onClick={async () => {
                if (args.contactId == null) return;
                await dataProvider.updateRenewalForecast(args.contactId, {
                  renewal_forecast_category: args.proposedCategory,
                  renewal_probability: args.proposedProbability,
                });
                respond({ approved: true });
                void logToolCall("updateRenewalForecast", {
                  contactName: args.contactName,
                  summary: `Approved renewal forecast for ${args.contactName}: ${args.currentCategory} → ${args.proposedCategory}`,
                });
              }}
            >
              Approve
            </Button>
            <Button
              size="sm"
              variant="outline"
              onClick={() => {
                respond({ approved: false });
                void logToolCall("updateRenewalForecast", {
                  contactName: args.contactName,
                  summary: `Rejected renewal forecast for ${args.contactName}`,
                });
              }}
            >
              Reject
            </Button>
          </div>
        )}
        {!isAdmin && (
          <p className="text-xs text-muted-foreground mt-2">
            Only admins can approve forecast changes.
          </p>
        )}
      </CardContent>
    </Card>
  );
}

