export function CopilotOverlayPanel() {
  const { close } = useCopilotOverlay();
  // Own the threadId here so the quick-action buttons and <CopilotChat>
  // operate on the same agent clone. CopilotKit clones agents per-thread
  // (getOrCreateThreadClone in react-core/v2); without a shared threadId,
  // useAgent() outside CopilotChat returns the BASE agent while CopilotChat
  // renders messages from a different cloned agent — meaning addMessage +
  // runAgent here would never appear in the chat panel.
  const [threadId, setThreadId] = useState<string>(() => randomUUID());

  useCopilotSetup({
    context: {
      description: "User is using the global CRM assistant",
      value: null,
    },
  });

  const handleNewConversation = useCallback(() => {
    setThreadId(randomUUID());
  }, []);

  const handleSelectThread = useCallback((id: string) => {
    setThreadId(id);
  }, []);

  // Escape key closes the panel
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") close();
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [close]);

  return (
    <div className="fixed right-0 top-[41px] bottom-0 w-92 bg-background shadow-lg z-50 flex flex-col border-l">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-2 border-b flex-shrink-0">
        <h3 className="text-sm font-medium">Copilot</h3>
        <Button variant="ghost" size="icon" className="h-7 w-7" onClick={close}>
          <X className="h-4 w-4" />
          <span className="sr-only">Close</span>
        </Button>
      </div>

      {/* Chat workspace (includes thread header, action buttons, chat, and thread history) */}
      <CopilotWorkspace
        agentId="overlay"
        className="flex-1 min-h-0"
        threadId={threadId}
        onNewConversation={handleNewConversation}
        onSelectThread={handleSelectThread}
      >
        {({ agent, runAgent }) => (
          <div className="flex gap-1.5 flex-wrap px-3 py-2 shrink-0">
            <Button
              variant="outline"
              size="sm"
              className="text-xs h-7"
              disabled={agent.isRunning}
              onClick={async () => {
                agent.addMessage({
                  id: randomUUID(),
                  role: "user",
                  content: "Search contacts in the CRM. Show results.",
                });
                await runAgent();
              }}
            >
              <Users className="h-3 w-3 mr-1" />
              Search Contacts
            </Button>
            <Button
              variant="outline"
              size="sm"
              className="text-xs h-7"
              disabled={agent.isRunning}
              onClick={async () => {
                agent.addMessage({
                  id: randomUUID(),
                  role: "user",
                  content: "Triage the top leads. Show the lead priority list.",
                });
                await runAgent();
              }}
            >
              <Users className="h-3 w-3 mr-1" />
              Lead Triage
            </Button>
          </div>
        )}
      </CopilotWorkspace>
    </div>
  );
}

